// seed: tests/seed.user1.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow, dismissMilestoneIfShown } from '../_helpers/milestone';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

test.describe('Достижения', () => {
  test('AC-02 Окно полученного достижения — строка ободрения, «חזרה למסך ראשי», шеринг с текстом и ссылкой #6a86f7d9 @prod-safe @mobile', async ({ page }) => {
    // Окно уровня «עלית דרגה» подавляем; автозакрытие выключено — тест сам открывает окно достижения (тот же MilestoneWindow).
    await suppressMilestoneWindow(page, { autoDismiss: false });

    // 1. До перехода: заменить navigator.share функцией, сохраняющей аргумент в window.__shared.
    await page.addInitScript(() => {
      (window as any).__shared = null;
      Object.defineProperty(navigator, 'share', {
        configurable: true,
        value: (data: unknown) => {
          (window as any).__shared = data;
          return Promise.resolve();
        },
      });
      Object.defineProperty(navigator, 'canShare', { configurable: true, value: () => true });
    });

    // 2. Открыть `/journey` → «30 תפילות: הושג».
    await page.goto('/journey');
    const badge = page.getByRole('button', { name: '30 תפילות: הושג' });
    await expect(badge).toBeVisible({ timeout: 20_000 });
    await dismissMilestoneIfShown(page);
    await badge.click();
    const dialog = page.getByRole('dialog');
    await expect(dialog.getByText('30 תפילות', { exact: true })).toBeVisible();
    await expect(dialog.getByText('שלושים תפילות — התפילה הופכת לחלק מהיום שלך')).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'חזרה למסך ראשי' })).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'שיתוף ההישג' })).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'סגירה' })).toBeVisible();

    // 3. «שיתוף ההישג» → предпросмотр → «המשך לשיתוף»; прочитать window.__shared.
    await dialog.getByRole('button', { name: 'שיתוף ההישג' }).click();
    await expect(dialog.getByText('זו ההודעה שתישלח, בלי שום פרט נוסף:')).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'ביטול' })).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'המשך לשיתוף' })).toBeVisible();
    await dialog.getByRole('button', { name: 'המשך לשיתוף' }).click();
    const expected =
      'השגתי את ההישג «30 תפילות» באפליקציית אור הגאולה. מצטרפים להתחזק בתפילה יחד?\nhttps://zichui-harabim.expo.app/';
    await expect
      .poll(async () => {
        const shared = await page.evaluate(() => (window as any).__shared);
        return shared ? `${shared.text ?? ''}${shared.url && !(shared.text ?? '').includes(shared.url) ? `\n${shared.url}` : ''}` : null;
      })
      .toBe(expected);

    // 4. Закрыть окно «סגירה».
    await page.getByRole('dialog').getByRole('button', { name: 'סגירה' }).click();
    await expect(page.getByRole('dialog')).toHaveCount(0);

    // 5. Открыть `/profile` → «אודות».
    await page.goto('/profile');
    await expect(page.getByRole('heading', { name: 'אודות' })).toBeVisible();
    await expect(page.getByText(/אפליקציית "אור הגאולה"/)).toBeVisible();
  });
});
